import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { LuSearch, LuRotateCcw, LuUsers } from 'react-icons/lu';
import { getStudents } from '../api/studentApi';
import type { Student } from '../api/studentApi';
import styles from './StudentManagement.module.css';

const ITEMS_PER_PAGE = 12;

/* ── Page ── */

export default function StudentManagement() {
  const navigate = useNavigate();

  /* API data */
  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const fetchStudents = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const data = await getStudents();
      setStudents(data);
    } catch {
      setError('학생 목록을 불러오는데 실패했습니다.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchStudents();
  }, [fetchStudents]);

  /* Filter inputs */
  const [searchStudentNumber, setSearchStudentNumber] = useState('');
  const [searchClass, setSearchClass] = useState('');
  const [searchName, setSearchName] = useState('');

  /* Applied filters */
  const [appliedFilters, setAppliedFilters] = useState({
    studentNumber: '',
    className: '',
    name: '',
  });

  /* Pagination */
  const [currentPage, setCurrentPage] = useState(1);

  /* Checkboxes */
  const [selectedIds, setSelectedIds] = useState<Set<number>>(new Set());

  const filteredStudents = students.filter((s) => {
    if (appliedFilters.studentNumber && !s.studentNumber.includes(appliedFilters.studentNumber)) {
      return false;
    }
    if (appliedFilters.name && !s.name.includes(appliedFilters.name)) {
      return false;
    }
    if (appliedFilters.className && !s.className.includes(appliedFilters.className)) {
      return false;
    }
    return true;
  });

  const totalPages = Math.max(1, Math.ceil(filteredStudents.length / ITEMS_PER_PAGE));
  const pageStudents = filteredStudents.slice(
    (currentPage - 1) * ITEMS_PER_PAGE,
    currentPage * ITEMS_PER_PAGE,
  );

  const handleSearch = () => {
    setAppliedFilters({
      studentNumber: searchStudentNumber.trim(),
      className: searchClass.trim(),
      name: searchName.trim(),
    });
    setCurrentPage(1);
  };

  const handleReset = () => {
    setSearchStudentNumber('');
    setSearchClass('');
    setSearchName('');
    setAppliedFilters({ studentNumber: '', className: '', name: '' });
    setCurrentPage(1);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleSearch();
  };

  const allChecked = pageStudents.length > 0 && pageStudents.every((s) => selectedIds.has(s.id));

  const toggleAll = () => {
    if (allChecked) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(pageStudents.map((s) => s.id)));
    }
  };

  const toggleOne = (id: number) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  };

  return (
    <div className={styles.page}>
      {/* Page Header */}
      <div className={styles.pageHeader}>
        <div className={styles.pageTitleGroup}>
          <LuUsers className={styles.pageTitleIcon} />
          <h2 className={styles.pageTitle}>학생관리</h2>
        </div>
      </div>

      {/* Filter Row */}
      <div className={styles.filterCard}>
        <div className={styles.filterRow}>
          <div className={styles.filterGroup}>
            <label className={styles.filterLabel} htmlFor="filter-sid">학번</label>
            <input
              id="filter-sid"
              className={styles.filterInput}
              type="text"
              placeholder=""
              value={searchStudentNumber}
              onChange={(e) => setSearchStudentNumber(e.target.value)}
              onKeyDown={handleKeyDown}
            />
          </div>

          <div className={styles.filterGroup}>
            <label className={styles.filterLabel} htmlFor="filter-class">반</label>
            <input
              id="filter-class"
              className={styles.filterInput}
              type="text"
              placeholder=""
              value={searchClass}
              onChange={(e) => setSearchClass(e.target.value)}
              onKeyDown={handleKeyDown}
            />
          </div>

          <div className={styles.filterGroup}>
            <label className={styles.filterLabel} htmlFor="filter-name">학생명</label>
            <input
              id="filter-name"
              className={styles.filterInputWide}
              type="text"
              placeholder=""
              value={searchName}
              onChange={(e) => setSearchName(e.target.value)}
              onKeyDown={handleKeyDown}
            />
          </div>

          <button className={styles.searchButton} type="button" onClick={handleSearch}>
            검색
          </button>

          <button className={styles.resetButton} type="button" onClick={handleReset}>
            초기화
          </button>
        </div>
      </div>

      {/* Student List Table */}
      <div className={styles.tableCard}>
        {loading ? (
          <div style={{ textAlign: 'center', padding: '32px', color: '#9ca3af' }}>불러오는 중...</div>
        ) : error ? (
          <div style={{ textAlign: 'center', padding: '32px', color: '#e74c3c' }}>{error}</div>
        ) : (
          <table className={styles.table}>
            <thead>
              <tr>
                <th className={styles.checkboxCol}>
                  <input
                    type="checkbox"
                    checked={allChecked}
                    onChange={toggleAll}
                  />
                </th>
                <th>이름</th>
                <th>학번</th>
                <th>반</th>
                <th>학년</th>
                <th>좌석</th>
                <th>전화번호</th>
              </tr>
            </thead>
            <tbody>
              {pageStudents.length === 0 ? (
                <tr className={styles.emptyRow}>
                  <td colSpan={7}>검색 결과가 없습니다.</td>
                </tr>
              ) : (
                pageStudents.map((student) => (
                  <tr
                    key={student.id}
                    onClick={() => navigate(`/students/${student.id}`)}
                    style={{ cursor: 'pointer' }}
                  >
                    <td
                      className={styles.checkboxCol}
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={selectedIds.has(student.id)}
                        onChange={() => toggleOne(student.id)}
                      />
                    </td>
                    <td>{student.name}</td>
                    <td>{student.studentNumber}</td>
                    <td>{student.className}</td>
                    <td>{student.grade}</td>
                    <td>{student.assignedSeatLabel || '-'}</td>
                    <td>{student.phone}</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        )}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div style={{ display: 'flex', justifyContent: 'center', gap: '4px', padding: '16px 0' }}>
          {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
            <button
              key={page}
              type="button"
              onClick={() => setCurrentPage(page)}
              style={{
                minWidth: '32px',
                height: '32px',
                borderRadius: '4px',
                border: 'none',
                background: 'none',
                cursor: 'pointer',
                fontWeight: page === currentPage ? 600 : 400,
                color: page === currentPage ? '#1a1a2e' : '#9ca3af',
              }}
            >
              {page}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
